MOD = 998244353
N = int(input())
P = list(map(lambda x: int(x)-1, input().split()))
S = input()

def countValidConfigurations():
    validCount = 0
    for mask in range(1 << N):
        spoon = [False] * N
        valid = True
        for i, p in enumerate(P):
            left_hand = (mask & (1 << i)) == 0
            if S[p] == 'L' or (S[p] == '?' and left_hand):
                if not spoon[p]:
                    spoon[p] = True
                else:
                    valid = False
                    break
            elif S[p] == 'R' or (S[p] == '?' and not left_hand):
                if not spoon[(p + 1) % N]:
                    spoon[(p + 1) % N] = True
                else:
                    valid = False
                    break
        if valid and all(spoon):
            validCount += 1
    return validCount % MOD

print(countValidConfigurations())
